      const left = i ? chars[i - 1] : "", right = j < n ? chars[j] : "";
      const joined = j - i === 1 && JOINERS.includes(c) && left && right && CAT_LETTER_MARK.test(left) &&
        CAT_LETTER_MARK.test(right) && !UNJOINED_SCRIPTS.has(script(left));
